# Zapisy można poprawiać przez wpisanie nowej treści (§ 7 ust. 2 pkt 1 rozporządzenia — ewidencja elektroniczna);
# trwała ma być historia: blokada zmian przenosi się z zapisów na ich wersje.
DROP_RECORD_GUARD = """
DROP TRIGGER IF EXISTS accounting_record_guard ON accounting_record;
DROP FUNCTION IF EXISTS satok_accounting_record_guard();
"""
RECORD_GUARD = """
CREATE OR REPLACE FUNCTION satok_accounting_record_guard() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'Zapisu w ewidencji przychodów i kosztów nie można zmienić ani usunąć — dodaj zapis korygujący';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER accounting_record_guard BEFORE UPDATE OR DELETE ON accounting_record
    FOR EACH ROW EXECUTE FUNCTION satok_accounting_record_guard();
"""
VERSION_GUARD = """
CREATE OR REPLACE FUNCTION satok_accounting_version_guard() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'Historii zapisów ewidencji nie można zmienić ani usunąć';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER accounting_recordversion_guard BEFORE UPDATE OR DELETE ON accounting_recordversion
    FOR EACH ROW EXECUTE FUNCTION satok_accounting_version_guard();
"""
DROP_VERSION_GUARD = """
DROP TRIGGER IF EXISTS accounting_recordversion_guard ON accounting_recordversion;
DROP FUNCTION IF EXISTS satok_accounting_version_guard();
"""


def first_versions(apps, schema_editor):
    Record = apps.get_model("accounting", "Record")
    RecordVersion = apps.get_model("accounting", "RecordVersion")
    fields = ("date", "document", "description", "counterparty", "revenue", "cost_deductible", "cost_other", "notes",
              "ksef_number", "attachment_sha256")
    for r in Record.objects.all():
        data = {f: (getattr(r, f).isoformat() if f == "date" else getattr(r, f)) for f in fields}
        RecordVersion.objects.create(record=r, version=1, action="utworzenie", data=data, by_id=r.created_by_id)


